import posthog from 'posthog-js';

const VN_PII_REGEX = /(?:\+?84|0)(?:3|5|7|8|9)\d{8}|\b\d{9,12}\b/g;

export function initHardenedPostHog() {
  if (typeof window === 'undefined') return;

  posthog.init(process.env.NEXT_PUBLIC_POSTHOG_KEY!, {
    // Di qua Next.js rewrite /ingest de tang do tin cay first-party truoc AdBlock
    api_host: '/ingest',
    ui_host: 'https://us.posthog.com',
    person_profiles: 'identified_only',
    capture_pageview: false, // Tu goi de gan kem campaign & event_id chuan
    session_recording: {
      // BAT BUOC giu true de che toan bo o nhap lieu ngay tai trinh duyet
      maskAllInputs: true,
      maskInputOptions: {
        password: true,
        tel: true,
        email: true,
        text: true,
        textarea: true,
        select: true,
      },
      // Chan luon cac vung DOM co gan class .ph-no-capture hoac thuoc tinh data-pii
      maskTextSelector: '.ph-no-capture, [data-pii="true"]',
      blockSelector: '.ph-block-vietqr, [data-payment-qr="true"]',
      // Lop phong thu bo sung neu input mang nhan dac thu hoac lo chuoi SDT/CCCD
      maskInputFn: (text, element) => {
        if (element?.getAttribute('data-allow-analytics') === 'search-keyword') {
          return text.replace(VN_PII_REGEX, '[MASKED_VN_ID]');
        }
        return '*'.repeat(Math.min(text.length, 12));
      },
    },
  });
}

export async function trackHighIntentWithCapiParity(params: {
  eventName: 'ViewPricingMatrix' | 'Interact3DModel' | 'SubmitLeadForm';
  unitCode?: string;
  valueVnd?: number;
}) {
  const eventId = crypto.randomUUID();

  // 1. Ghi nhan hanh vi tren PostHog de do Heatmap, Funnel & A/B Variant
  posthog.capture(params.eventName, {
    event_id: eventId,
    unit_code: params.unitCode,
    value_vnd: params.valueVnd,
  });

  // 2. Day dong bo cung event_id ve backend de Server-Side CAPI loai trung voi Pixel
  await fetch('/api/tracking/server-capi-relay', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    keepalive: true,
    body: JSON.stringify({
      eventName: params.eventName,
      eventId,
      sourceUrl: window.location.href,
      unitCode: params.unitCode,
    }),
  });
}
